Here's the complete updated component with client-side validation added (name required, email format check, message non-empty), with inline error messages styled to match the existing design language, and error borders on invalid fields. As requested, I have **not** modified the file — this is for you to review and apply.

```tsx
"use client"

import { useState } from "react"
import { SectionSep } from "@/components/ui/SectionHeader"
import { PROFILE } from "@/lib/content"

const META = [
  { label: "Email",        value: PROFILE.socials.email },
  { label: "Role",         value: "AI + Full-stack"     },
  { label: "Availability", value: PROFILE.status        },
  { label: "Response",     value: "Within 24 hours"     },
]

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

type Errors = { name?: string; email?: string; message?: string }

function validate(form: { name: string; email: string; message: string }): Errors {
  const errors: Errors = {}
  if (!form.name.trim()) errors.name = "Name is required"
  if (!form.email.trim()) errors.email = "Email is required"
  else if (!EMAIL_RE.test(form.email.trim())) errors.email = "Enter a valid email"
  if (!form.message.trim()) errors.message = "Message is required"
  return errors
}

export function ContactSection() {
  const [form, setForm] = useState({ name: "", email: "", message: "" })
  const [errors, setErrors] = useState<Errors>({})
  const [status, setStatus] = useState<"idle" | "loading" | "success" | "error">("idle")

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    const nextErrors = validate(form)
    setErrors(nextErrors)
    if (Object.keys(nextErrors).length > 0) return

    setStatus("loading")
    try {
      const res = await fetch("/api/contact", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      })
      if (res.ok) { setStatus("success"); setForm({ name: "", email: "", message: "" }); setErrors({}) }
      else setStatus("error")
    } catch { setStatus("error") }
  }

  function inputStyleFor(field: keyof Errors): React.CSSProperties {
    return {
      width: "100%",
      minHeight: 46,
      border: `1px solid ${errors[field] ? "var(--accent-error, #e5484d)" : "var(--border-default)"}`,
      borderRadius: "var(--radius-sm)",
      background: "var(--bg)",
      color: "var(--text-primary)",
      padding: "12px 13px",
      fontSize: 14,
      outline: "none",
      fontFamily: "var(--font-sans)",
      transition: "border-color 180ms var(--ease-standard), background 180ms var(--ease-standard), box-shadow 180ms var(--ease-standard)",
      boxSizing: "border-box",
    }
  }

  function onFocus(e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) {
    e.currentTarget.style.background = "var(--surface-2)"
    e.currentTarget.style.boxShadow = "0 0 0 3px rgba(255,255,255,0.055)"
  }
  function onBlur(e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) {
    e.currentTarget.style.background = "var(--bg)"
    e.currentTarget.style.boxShadow = "none"
  }

  function clearError(field: keyof Errors) {
    setErrors(prev => {
      if (!prev[field]) return prev
      const next = { ...prev }
      delete next[field]
      return next
    })
  }

  const errorTextStyle: React.CSSProperties = {
    fontSize: 12,
    color: "var(--accent-error, #e5484d)",
    margin: "6px 0 0",
  }

  return (
    <section id="contact" className="section">
      <SectionSep number="08" label="Contact" />
      <div className="section-content">
        <h2 className="section-title">Let&apos;s Build Something</h2>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "minmax(0, 0.9fr) minmax(380px, 1.1fr)",
            gap: 16,
            alignItems: "start",
          }}
        >
          {/* Left — meta */}
          <div>
            <p style={{ fontSize: 15, color: "var(--text-secondary)", lineHeight: 1.7, margin: "0 0 28px" }}>
              Have an AI system, backend workflow, or project in mind? Send me a note.
            </p>

            {/* 2×2 meta grid */}
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: 10,
              }}
            >
              {META.map(({ label, value }) => (
                <div
                  key={label}
                  style={{
                    border: "1px solid var(--border-default)",
                    borderRadius: "var(--radius-md)",
                    background: "var(--surface-1)",
                    padding: 16,
                  }}
                >
                  <p style={{ fontSize: 11, color: "var(--text-faint)", fontFamily: "var(--font-mono)", textTransform: "uppercase", letterSpacing: "0.06em", margin: "0 0 6px" }}>
                    {label}
                  </p>
                  <p style={{ fontSize: 13, color: "var(--text-secondary)", margin: 0 }}>{value}</p>
                </div>
              ))}
            </div>
          </div>

          {/* Right — form */}
          <div
            style={{
              border: "1px solid var(--border-default)",
              borderRadius: "var(--radius-lg)",
              background: "var(--surface-1)",
              padding: 24,
            }}
          >
            {status === "success" ? (
              <div style={{ textAlign: "center", padding: "40px 0" }}>
                <p style={{ fontSize: 28, margin: "0 0 12px" }}>✓</p>
                <p style={{ fontSize: 15, color: "var(--text-primary)", margin: "0 0 6px", fontWeight: 500 }}>Message sent</p>
                <p style={{ fontSize: 13, color: "var(--text-muted)", margin: 0 }}>I&apos;ll get back to you within 24 hours.</p>
              </div>
            ) : (
              <form onSubmit={handleSubmit} noValidate style={{ display: "flex", flexDirection: "column", gap: 14 }}>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                  <div>
                    <label style={{ display: "block", fontSize: 11, color: "var(--text-faint)", fontFamily: "var(--font-mono)", textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 6 }}>Name</label>
                    <input
                      type="text"
                      value={form.name}
                      onChange={e => { setForm(f => ({ ...f, name: e.target.value })); clearError("name") }}
                      placeholder="Your name"
                      style={inputStyleFor("name")}
                      onFocus={onFocus}
                      onBlur={onBlur}
                      aria-invalid={!!errors.name}
                    />
                    {errors.name && <p style={errorTextStyle}>{errors.name}</p>}
                  </div>
                  <div>
                    <label style={{ display: "block", fontSize: 11, color: "var(--text-faint)", fontFamily: "var(--font-mono)", textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 6 }}>Email</label>
                    <input
                      type="email"
                      value={form.email}
                      onChange={e => { setForm(f => ({ ...f, email: e.target.value })); clearError("email") }}
                      placeholder="you@email.com"
                      style={inputStyleFor("email")}
                      onFocus={onFocus}
                      onBlur={onBlur}
                      aria-invalid={!!errors.email}
                    />
                    {errors.email && <p style={errorTextStyle}>{errors.email}</p>}
                  </div>
                </div>
                <div>
                  <label style={{ display: "block", fontSize: 11, color: "var(--text-faint)", fontFamily: "var(--font-mono)", textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 6 }}>Message</label>
                  <textarea
                    value={form.message}
                    onChange={e => { setForm(f => ({ ...f, message: e.target.value })); clearError("message") }}
                    placeholder="Tell me about your project..."
                    rows={5}
                    style={{ ...inputStyleFor("message"), resize: "vertical", minHeight: 132 }}
                    onFocus={onFocus}
                    onBlur={onBlur}
                    aria-invalid={!!errors.message}
                  />
                  {errors.message && <p style={errorTextStyle}>{errors.message}</p>}
                </div>
                {status === "error" && (
                  <p style={{ fontSize: 12, color: "var(--text-muted)", margin: 0 }}>
                    Something went wrong — email me directly at {PROFILE.socials.email}
                  </p>
                )}
                <button
                  type="submit"
                  disabled={status === "loading"}
                  className="btn-primary"
                  style={{ opacity: status === "loading" ? 0.7 : 1, cursor: status === "loading" ? "wait" : "pointer" }}
                >
                  {status === "loading" ? "Sending…" : <>Send Message <span className="btn-arrow">→</span></>}
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    </section>
  )
}
```

Notes on the approach:
- Removed `required` HTML attributes (and added `noValidate`) in favor of custom validation, so error messages are styled consistently rather than using the browser's native tooltip.
- Errors clear as soon as the user edits the corresponding field, and are (re)computed on submit.
- Used `var(--accent-error, #e5484d)` as the error color with a fallback in case that CSS variable isn't defined in `globals.css` — worth checking and swapping for an exact token if one exists.
- Kept the focus/blur hover styling but stopped it from overriding the error border color (border color now derives from `errors[field]` instead of being reset by `onFocus`/`onBlur`).
